const openScansForPath = `-- name: OpenScansForPath :many
SELECT id, canonical_path, categories_json, scanner_id, claimed_by, claim_token, attempt, heartbeat_at, lease_expires_at, status, result_json, created_at,
       delegation_id, head_sha, source_snapshot_id, replacement_scan_id, trigger, completed_at, paths_json, reuse_key, error,
       guidance_json, ingest_json, runtime_json, progress_json, delta_json, started_at, long_running_at
FROM code_scans
WHERE canonical_path = ? AND status IN ('pending', 'running')
ORDER BY created_at
`

func (q *Queries) OpenScansForPath(ctx context.Context, canonicalPath string) ([]CodeScans, error) {
	rows, err := q.db.QueryContext(ctx, openScansForPath, canonicalPath)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []CodeScans
	for rows.Next() {
		var i CodeScans
		if err := rows.Scan(
			&i.ID,
			&i.CanonicalPath,
			&i.CategoriesJson,
			&i.ScannerID,
			&i.ClaimedBy,
			&i.ClaimToken,
			&i.Attempt,
			&i.HeartbeatAt,
			&i.LeaseExpiresAt,
			&i.Status,
			&i.ResultJson,
			&i.CreatedAt,
			&i.DelegationID,
			&i.HeadSha,
			&i.SourceSnapshotID,
			&i.ReplacementScanID,
			&i.Trigger,
			&i.CompletedAt,
			&i.PathsJson,
			&i.ReuseKey,
			&i.Error,
			&i.GuidanceJson,
			&i.IngestJson,
			&i.RuntimeJson,
			&i.ProgressJson,
			&i.DeltaJson,
			&i.StartedAt,
			&i.LongRunningAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

