const resolveCodeScanIDsByPrefix = `-- name: ResolveCodeScanIDsByPrefix :many
SELECT id
FROM code_scans
WHERE canonical_path = ?1
  AND id >= ?2
  AND id < ?3
ORDER BY id
LIMIT 2
`

type ResolveCodeScanIDsByPrefixParams struct {
	CanonicalPath string `json:"canonical_path"`
	Prefix        string `json:"prefix"`
	PrefixEnd     string `json:"prefix_end"`
}

func (q *Queries) ResolveCodeScanIDsByPrefix(ctx context.Context, arg ResolveCodeScanIDsByPrefixParams) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, resolveCodeScanIDsByPrefix, arg.CanonicalPath, arg.Prefix, arg.PrefixEnd)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

